import sys
import xml.etree.ElementTree as ET

A = "{http://schemas.android.com/apk/res/android}"

def triage(path):
    root = ET.parse(path).getroot()
    app = root.find("application")
    sdk = root.find("uses-sdk")
    print(f"== {root.get('package')} (minSdk {sdk.get(A+'minSdkVersion')}, "
          f"targetSdk {sdk.get(A+'targetSdkVersion')})")
    if app.get(A + "debuggable") == "true":
        print("  [high] android:debuggable=true in a release build")
    if app.get(A + "allowBackup") == "true":
        print("  [info] allowBackup=true: check what lands in backups")
    for comp in app:
        name = comp.get(A + "name")
        exported = comp.get(A + "exported")
        filters = comp.findall("intent-filter")
        perm = comp.get(A + "permission")
        launcher = any(c.get(A + "name", "").endswith("LAUNCHER")
                       for f in filters for c in f.findall("category"))
        if exported is None and filters:
            print(f"  [check] {comp.tag} {name}: has intent filter, exported not set")
        if exported == "true" and not launcher and perm is None:
            print(f"  [review] {comp.tag} {name}: exported, no permission")
        for f in filters:
            for d in f.findall("data"):
                if d.get(A + "scheme") not in (None, "http", "https"):
                    print(f"  [review] deep link {d.get(A+'scheme')}://{d.get(A+'host')} "
                          f"(custom scheme, unverifiable)")

for p in sys.argv[1:]:
    triage(p)

import os, re, sys

PATTERNS = {
    "password": re.compile(rb"pass(word)?[=:]\s*\S+", re.I),
    "email": re.compile(rb"[\w.+-]+@[\w-]+\.[\w.]+"),
    "bearer token": re.compile(rb"Bearer\s+[A-Za-z0-9._-]{20,}"),
}

def scan(root):
    for dirpath, _, files in os.walk(root):
        for name in sorted(files):
            path = os.path.join(dirpath, name)
            data = open(path, "rb").read()
            for label, rx in PATTERNS.items():
                for m in rx.finditer(data):
                    print(f"{os.path.relpath(path, root)}: {label}: {m.group(0).decode(errors='replace')}")

scan(sys.argv[1])

