// Vulnerable: exported in the manifest so a partner app can open it
class ForwardActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val next = intent.getParcelableExtra("next", Intent::class.java)
        if (next != null) startActivity(next)  // runs with THIS app's identity
        finish()
    }
}

// Fixed: 1) the manifest says android:exported="false" unless the screen
//    truly must be public; 2) a forwarded intent is rebuilt from an allowlist.
class ForwardActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val next = intent.getParcelableExtra("next", Intent::class.java)
        if (next != null) {
            val safe = IntentSanitizer.Builder()
                .allowComponent(ComponentName(this, OrderDetailsActivity::class.java))
                .allowExtra("orderId", String::class.java)
                .build()
                .sanitizeByThrowing(next)   // throws if anything else is present
            startActivity(safe)
        }
        finish()
    }
}

import java.io.File;
import java.io.IOException;
import java.util.UUID;

public class SafeCache {
    static final File APP = new File("/data/data/com.example.share/files");
    static final File INBOX = new File(APP, "inbox");

    // Vulnerable: trusts the name the sending app's provider reports
    static File weakTarget(String displayName) {
        return new File(INBOX, displayName);
    }

    // Fixed (preferred): ignore the sender's name entirely
    static File randomTarget() {
        return new File(INBOX, UUID.randomUUID().toString());
    }

    // Fixed (if a name is needed): canonicalise, then require the inbox prefix
    static File checkedTarget(String displayName) throws IOException {
        File f = new File(INBOX, displayName);
        String inbox = INBOX.getCanonicalPath() + File.separator;
        if (!f.getCanonicalPath().startsWith(inbox)) {
            throw new IOException("rejected: " + displayName);
        }
        return f;
    }
    // main() prints each target for two names (omitted)
}

