import java.net.URI;
import java.util.Set;

public class LinkCheck {
    // Vulnerable: a partial string comparison
    static boolean weakAllowed(String url) {
        return url.contains("shop.example.com");
    }

    // Fixed: parse, then compare scheme and the exact host
    static final Set<String> ALLOWED = Set.of("shop.example.com", "help.example.com");
    static boolean allowed(String url) {
        try {
            URI u = new URI(url);
            return "https".equals(u.getScheme())
                && u.getHost() != null
                && ALLOWED.contains(u.getHost().toLowerCase());
        } catch (Exception e) {
            return false;
        }
    }
    // main() runs both checks on five URLs (omitted)
}

