class PromoWebActivity : AppCompatActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val webView = WebView(this).also { setContentView(it) }
        val url = intent.data?.getQueryParameter("url") ?: return finish()
        webView.settings.javaScriptEnabled = true
        webView.addJavascriptInterface(AccountBridge(session), "account") // every frame, any origin
        webView.loadUrl(url)                                               // whatever the link says
    }
}

// Fixed: only our own https pages load, and only they can reach the bridge
