prompt.authenticate(promptInfo)                      // no CryptoObject

// Fixed (crypto-bound): the Keystore key only works after a fresh strong biometric
KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore").apply {
    init(KeyGenParameterSpec.Builder("vault_key",
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
        .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
        .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
        .setUserAuthenticationRequired(true)
        .setUserAuthenticationParameters(0, KeyProperties.AUTH_BIOMETRIC_STRONG) // 0 = every use
        .setInvalidatedByBiometricEnrollment(true)
        .build())
    generateKey()
}

// Later: unlock = decrypt, and the cipher only works inside a successful prompt
